'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('circuits'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,switches=[false,false,false],solved=false,hintDepth=0,state='ready',saveFailed=false;
const names=[['The silent lantern','沉睡的燈'],['The two passages','兩條通道'],['The shared gateway','共用關口']];
function targetFor(v,s){return s===0?[true]:s===1?[[true,false],[false,true],[true,true]][v%3]:Math.floor(v/3)===0?[false,true]:[true,false];}
function initialFor(v,s){return s===0?[[false,false,false],[false,true,false],[true,false,false]][v%3]:s===1?[false,false,false]:[true,true,false];}
function lights(s,sw){return s===0?[sw[0]&&sw[1]]:s===1?[sw[0],sw[1]]:[sw[0]&&sw[2],sw[1]&&sw[2]];}
function matches(){const actual=lights(stage,switches);return targetFor(variant,stage).every((x,i)=>x===actual[i]);}
function resetPanel(){switches=initialFor(variant,stage).slice();solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('circuits')){variant=v;stage=0;resetPanel();}
function toggle(i){if(solved||!Number.isInteger(i)||i<0||i>(stage===2?2:1))return;switches[i]=!switches[i];state='changed';render();}
function check(){if(solved)return;if(!matches()){state='wrong';render();return;}solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('spark');render();if(stage<2)$('next').focus();}
function wire(d,on){return `<path d="${d}" class="wire ${on?'live':''}"/>`;}
function switchDrawing(x,y,i,on){return `<circle cx="${x-24}" cy="${y}" r="5" class="switch-contact"/><circle cx="${x+24}" cy="${y}" r="5" class="switch-contact"/>${wire(`M${x-24} ${y}L${x+24} ${switches[i]?y:y-28}`,on)}<text x="${x}" y="${y+32}" text-anchor="middle" class="circuit-label">${'ABC'[i]}</text>`;}
function bulb(x,y,on,label){return `<circle cx="${x}" cy="${y}" r="23" class="bulb ${on?'lit':''}"/><path d="M${x-14} ${y-14}l28 28m0 -28l-28 28" class="glyph ${on?'lit':''}"/><text x="${x}" y="${y+48}" text-anchor="middle" class="circuit-label">${label}</text>`;}
function diagram(){const on=lights(stage,switches),any=on.some(Boolean);let drawing=wire('M60 260H40V80',any)+wire(stage===0?'M160 260H480V80':'M160 260H480V180',any)+wire('M60 260H100 M122 260H160',any)+'<path d="M100 236V284M122 247V273" class="cell"/><text x="78" y="232" class="circuit-label">+</text><text x="125" y="242" class="circuit-label">−</text>';
 if(stage===0)drawing+=wire('M40 80H136 M184 80H266 M314 80H377 M423 80H480',on[0])+switchDrawing(160,80,0,on[0])+switchDrawing(290,80,1,on[0])+bulb(400,80,on[0],'1');
 else{drawing+=stage===2?wire('M40 80H66 M114 80H160',any)+switchDrawing(90,80,2,any):wire('M40 80H160',any);drawing+=wire('M160 80V180',on[1])+wire('M480 180V80',on[0])+wire('M160 80H226 M274 80H377 M423 80H480',on[0])+wire('M160 180H226 M274 180H377 M423 180H480',on[1])+switchDrawing(250,80,0,on[0])+switchDrawing(250,180,1,on[1])+bulb(400,80,on[0],'1')+bulb(400,180,on[1],'2');drawing+='<circle cx="160" cy="80" r="5" class="switch-contact"/><circle cx="480" cy="80" r="5" class="switch-contact"/>';}
 return `<svg viewBox="0 0 520 310" aria-hidden="true">${drawing}<text x="210" y="289" class="circuit-label">${t('Battery','電池')}</text></svg>`;}
function lampCards(values){return `<div class="lamp-row">${values.map((on,i)=>`<div class="lamp-card"><svg class="lamp-icon" viewBox="0 0 40 50" aria-hidden="true"><circle cx="20" cy="18" r="15" class="bulb ${on?'lit':''}"/><path d="M12 35H28M14 41H26" class="cell"/></svg><span><strong>${t('Lamp','燈')} ${i+1}</strong>${on?t('Lit','亮'):t('Unlit','不亮')}</span></div>`).join('')}</div>`;}
function hints(){const goal=targetFor(variant,stage);const solution=stage===0?t('Close A and B to complete the loop.','閉合 A 和 B，接通整個迴路。'):t(`Set A ${goal[0]?'closed':'open'} and B ${goal[1]?'closed':'open'}${stage===2?', and close C':''}.`,`把 A ${goal[0]?'閉合':'斷開'}、B ${goal[1]?'閉合':'斷開'}${stage===2?'，並閉合 C':''}。`);return[t('Trace a path from one battery terminal through a lamp and back to the other terminal. Does a gap interrupt it?','從電池一端沿導線經過燈，再回到另一端。有缺口截斷通路嗎？'),stage===0?t('Both switches sit on the same loop. Try changing one at a time.','兩個開關在同一迴路上。試試每次只改一個。'):stage===1?t('Each lamp has its own branch switch. One branch can remain complete when the other is open.','每盞燈各有一個支路開關。一條支路斷開時，另一條仍可保持接通。'):t('Switch C is before the split. Both branches share that part of the path.','C 開關位於分支之前。兩條支路都共用那一段通路。'),solution];}
function render(){const actual=lights(stage,switches),goal=targetFor(variant,stage),complete=solved&&stage===2,count=stage+Number(solved);document.title=t('The Lantern Circuit · Orion','星燈迴路 · Orion');$('stageTitle').textContent=t(...names[stage]);$('progressCount').textContent=t(`Panels restored · ${count} / 3`,`已修復 ${count} / 3 塊電路板`);$('progressBar').value=count;$('stageLabel').textContent=t(`PANEL ${stage+1} · SET ${variant+1}`,`電路板 ${stage+1} · 圖案組 ${variant+1}`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('sceneStatus').textContent=complete?t('The star chart is awake.','星圖甦醒了。'):t('Restore the lantern gallery.','修復星燈長廊。');$('diagram').innerHTML=diagram();$('diagram').setAttribute('aria-label',t(stage===0?'One battery loop: switch A, switch B, lamp 1.':stage===1?'Two branches: A controls lamp 1, B controls lamp 2.':'Switch C is shared before two branches: A with lamp 1 and B with lamp 2.',stage===0?'一個電池迴路：開關 A、開關 B、燈 1。':stage===1?'兩條支路：A 控制燈 1，B 控制燈 2。':'開關 C 在分支前共用：A 與燈 1 在一條支路，B 與燈 2 在另一條。'));
 for(let i=0;i<3;i++){const b=$(`switch${'ABC'[i]}`);b.hidden=i===2&&stage!==2;b.disabled=solved;b.setAttribute('aria-pressed',String(switches[i]));b.textContent=`${'ABC'[i]} · ${switches[i]?t('Closed','閉合'):t('Open','斷開')}`;b.setAttribute('aria-label',t(`Switch ${'ABC'[i]}: ${switches[i]?'closed':'open'}. Tap to toggle.`,`開關 ${'ABC'[i]}：${switches[i]?'閉合':'斷開'}。點按以切換。`));}
 $('goal').innerHTML=`<h3>${t('MATCH THIS PATTERN','配對這個圖案')}</h3>${lampCards(goal)}`;$('reading').innerHTML=`<h3>${t('YOUR LAMPS NOW','現在的燈光')}</h3>${lampCards(actual)}`;
 const messages={ready:t('Try the switches and watch what changes.','試試開關，觀察變化。'),changed:matches()?t('The lamps match! Check your pattern to restore this panel.','燈光配對成功！按檢查修復這塊板。'):t('Keep exploring. Compare each lamp with the target above.','繼續探索，把每盞燈與上方目標比較。'),wrong:t('Not yet. The current lights differ from the target. Follow the wires and try another switch.','還未配對。現在的燈光與目標不同。沿著導線觀察，再試另一個開關。'),success:complete?t('All three panels restored! The Spark Sigil is yours.','三塊電路板已修復！你獲得火花符印。'):t('Pattern matched. A bronze seal opens.','圖案配對成功，一道青銅封印打開了。')};$('feedback').textContent=messages[state];$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(x=>`<li>${x}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but this browser could not save it. Try saving again.','已獲得符印，但瀏覽器無法儲存。請再次嘗試。'):OrionProgress.has('spark')?t('Spark Sigil saved in your collection.','火花符印已存入你的收藏。'):'';
}
for(let i=0;i<3;i++)$(`switch${'ABC'[i]}`).onclick=()=>toggle(i);$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetPanel();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetPanel();$('switchA').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const next=OrionProgress.nextVariant('circuits',variant);observedVariant=OrionProgress.variant('circuits');resetMission(next);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('spark');render();};
function syncProgress(){const v=OrionProgress.variant('circuits'),target=OrionProgress.read().hashTarget,changed=v!==observedVariant||target!==observedTarget;observedVariant=v;observedTarget=target;if(changed||solved&&stage===2&&!OrionProgress.has('spark')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
